mapper.select:
SELECT poi.OUTSOURCNAME, psc.CONTRACT_NAME, pso.JOB_ID, pso.USER_NAME, pso.EVALUATION_LEVEL, pso.PRICE, pso.WORK_TIME, pso.WORK_BEGIN_DATE, pso.WORK_END_DATE, psc.CONTRACT_NO,
CASE WHEN #{startDate, jdbcType=TIMESTAMP} IS NULL THEN pso.WORK_BEGIN_DATE ELSE GREATEST(pso.WORK_BEGIN_DATE, #{startDate, jdbcType=TIMESTAMP}) END AS INTERSECT_START,
CASE WHEN #{endDate, jdbcType=TIMESTAMP} IS NULL THEN NVL(pso.WORK_END_DATE, SYSDATE) ELSE LEAST(NVL(pso.WORK_END_DATE, SYSDATE), #{endDate, jdbcType=TIMESTAMP}) END AS INTERSECT_END FROM PPM_SUPPLIER_OUTSOURCING pso INNER JOIN PPM_SUPPLIER_CONTRACT psc ON (pso.RELATE_ID = psc.ID) LEFT JOIN PPM_OUTSOURCING_INFO poi ON (psc.SUPPLIER_ID = poi.ORGCODE) LEFT JOIN PPM_OUTSOURCING_BASIC pob ON (pso.JOB_ID = pob.JOB_ID)
AND pso.USER_NAME = #{userName}
AND pob.DEPT_ID = #{deptValue}
AND pob.PERSON_IN_CHARGE = #{pmId}
AND psc.SUPPLIER_ID = #{supplierId}
AND pso.WORK_BEGIN_DATE <= #{endDate, jdbcType=TIMESTAMP} AND (pso.WORK_END_DATE >= #{startDate, jdbcType=TIMESTAMP} OR pso.WORK_END_DATE IS NULL)
ORDER BY psc.CREATE_DATE DESC, pso.CREATE_DATE DESC
